// Mobile Menu Toggle
// ============================================================================

const menuToggle = document.querySelector('.menu-toggle');
const navMenu = document.getElementById('nav-menu');

menuToggle.addEventListener('click', () => {
    const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
    menuToggle.setAttribute('aria-expanded', !isExpanded);
    navMenu.classList.toggle('active');
});

// Close menu when a link is clicked
document.querySelectorAll('.nav-menu a').forEach(link => {
    link.addEventListener('click', () => {
        menuToggle.setAttribute('aria-expanded', false);
        navMenu.classList.remove('active');
    });
});

// Close menu when clicking outside
document.addEventListener('click', (e) => {
    if (!e.target.closest('.navbar')) {
        menuToggle.setAttribute('aria-expanded', false);
        navMenu.classList.remove('active');
    }
});

// ============================================================================
// Add to Cart Functionality
// ============================================================================

const cartNotification = document.getElementById('cart-notification');
let cartCount = 0;

document.querySelectorAll('.add-to-cart').forEach(button => {
    button.addEventListener('click', (e) => {
        const productCard = e.target.closest('.product-card');
        const productName = productCard.querySelector('.product-info h3').textContent;

        cartCount++;
        showNotification(`✓ ${productName} added to cart`);

        // Add visual feedback
        button.textContent = 'Added!';
        button.style.opacity = '0.7';
        setTimeout(() => {
            button.textContent = 'Add to Cart';
            button.style.opacity = '1';
        }, 1500);
    });
});

// ============================================================================
// Shop Now Button Functionality
// ============================================================================

document.querySelectorAll('.shop-button').forEach(button => {
    button.addEventListener('click', (e) => {
        const dealCard = e.target.closest('.deal-card');
        const dealTitle = dealCard.querySelector('.deal-content h3').textContent;
        showNotification(`🛍️ Browsing ${dealTitle}...`);
    });
});

// ============================================================================
// Newsletter Subscription
// ============================================================================

const newsletterForm = document.querySelector('.newsletter-form');

newsletterForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const emailInput = document.getElementById('email');
    const email = emailInput.value;

    if (email) {
        showNotification(`✓ Thanks! Check ${email} for exclusive deals.`);
        emailInput.value = '';
    }
});

// ============================================================================
// Notification System
// ============================================================================

function showNotification(message) {
    cartNotification.textContent = message;
    cartNotification.classList.add('show');

    // Auto-hide after 3 seconds
    setTimeout(() => {
        cartNotification.classList.remove('show');
    }, 3000);
}

// ============================================================================
// CTA Button
// ============================================================================

document.querySelector('.cta-button').addEventListener('click', () => {
    document.getElementById('featured').scrollIntoView({ behavior: 'smooth' });
});

// ============================================================================
// Icon Button Interactivity
// ============================================================================

document.querySelectorAll('.icon-button').forEach(button => {
    button.addEventListener('click', (e) => {
        const label = button.getAttribute('aria-label');
        if (label.includes('cart')) {
            showNotification(`🛒 ${label} (${cartCount} items)`);
        } else if (label.includes('search')) {
            showNotification('🔍 Search feature coming soon!');
        }
    });
});

// ============================================================================
// Smooth Scrolling for Anchor Links
// ============================================================================

document.querySelectorAll('a[href^="#"]').forEach(anchor => {
